import{z as p,x as i,o as t,c as B,q as A,j as s,D as r,d as a,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"预编译与计划缓存","description":"","frontmatter":{"title":"预编译与计划缓存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/prepared-plan-cache.md","filePath":"cs/prepared-plan-cache.md","lastUpdated":1791063341000}'),d={name:"cs/prepared-plan-cache.md"};function c(C,E,m,h,P,T){const n=i("Mermaid");return t(),B("div",null,[E[2]||(E[2]=A('<h1 id="预编译与计划缓存" tabindex="-1">预编译与计划缓存 <a class="header-anchor" href="#预编译与计划缓存" aria-label="Permalink to &quot;预编译与计划缓存&quot;">​</a></h1><div class="epigraph"><p>语句先解析、绑定类型、优化成计划；同一形状反复出现时，缓存计划摊掉优化，也可能把第一次的基数赌局锁死。</p><footer>—— 据 Selinger et al. 优化在路径选择之前；Ramakrishnan and Gehrke；PostgreSQL / SQL 标准对 prepared statement 的整理</footer></div><p><a href="/cs/connection-pooling">上一课</a>让同一后端反复服务请求。本课不调池大小。缺口是语句路径：文本 SQL 每次解析、分析、优化代价不低。预编译（prepared statement）把解析与（可选）计划钉在会话或全局缓存里，执行只传绑定参数。查询语言进阶在此收口，下一单元才回依赖理论。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干 <a href="/cs/query-plan">查询计划</a> 假定一次优化。OLTP 同一条 <code>WHERE id = $1</code> 每秒成千上万次，重复优化浪费 CPU，也增加锁在解析器上的时间。预编译：<code>PREPARE</code> 得到句柄；<code>EXECUTE</code> 带参数。缺口是<strong>计划是否在绑参数之前就定死</strong>：参数未到时只能用平均选择率；第一次执行的参数若极特殊，缓存计划可能永远选错路径。</p><p>绑定窥视（bind peeking）：用第一次（或每次）参数再优化。通用计划：不看参数。两种策略在倾斜数据上行为相反。本课钉权衡，不把某一产品默认当理论。</p><p><span class="marginnote">SQL 注入：预编译把参数当数据不进解析器，是正确性与安全的同一机制。ORM 若退回拼字符串，池与预编译都救不了。</span></p><p><span class="marginnote">直觉类比：计划缓存像记住了「去公司常走的那条路」，省掉每次重新导航；但某天参数换了、路况变了，照旧走反而更慢——缓存省的是规划时间，赌的是「路况不变」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>客户端：参数化 API，禁止拼值。服务端：会话级准备语句，或全局计划缓存按文本+常量折叠后的形状索引。失效：统计更新、索引增减、模式版本（上一课迁移）必须丢缓存。</p><p>与存储过程：过程体内语句同样走缓存；过程本身是另一层句柄。本课不把二者当成一种对象。</p>',11)),(t(),s(o,null,{default:r(()=>[l(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22SQL%20%E6%96%87%E6%9C%AC%22%5D%20--%3E%20PARSE%5B%22%E8%A7%A3%E6%9E%90%20%2F%20%E5%88%86%E6%9E%90%22%5D%0A%20%20PARSE%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%E6%88%90%E8%AE%A1%E5%88%92%22%5D%0A%20%20OPT%20--%3E%20CACHE%5B%22%E8%AE%A1%E5%88%92%E7%BC%93%E5%AD%98%22%5D%0A%20%20CACHE%20--%3E%20EXEC%5B%22%E7%BB%91%E5%AE%9A%E5%8F%82%E6%95%B0%E6%89%A7%E8%A1%8C%22%5D%0A%20%20STAT%5B%22%E7%BB%9F%E8%AE%A1%20%2F%20%E6%A8%A1%E5%BC%8F%E5%8F%98%E6%9B%B4%22%5D%20--%3E%20INV%5B%22%E5%A4%B1%E6%95%88%22%5D%0A%20%20INV%20--%3E%20OPT%0A"})]),fallback:r(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("代价模型仍用 "),e("a",{href:"/cs/histogram-card"},"直方图"),a("。缓存命中跳过搜索，等于假设「形状不变则计划不变」。倾斜、数据涨一个数量级、参数从「一个 id」变成「半个表的范围」，假设破裂，表现为突然变慢——后课计划回归专门命名。本课只要求：缓存是性能合同，不是语义合同；结果应与每次重优化相同（忽略计划导致的超时差异）。")],-1)),E[5]||(E[5]=e("p",null,"第一次执行时「窥视」还是「不看参数」，在倾斜数据上的风险不同：",-1)),(t(),s(o,null,{default:r(()=>[l(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIRST%5B%22%E7%AC%AC%E4%B8%80%E6%AC%A1%20EXECUTE%20%E5%88%B0%E8%BE%BE%22%5D%20--%3E%20PEEK%7B%22%E9%87%87%E7%94%A8%E5%93%AA%E7%A7%8D%E8%AE%A1%E5%88%92%E7%AD%96%E7%95%A5%22%7D%0A%20%20PEEK%20--%3E%7C%22%E7%AA%A5%E8%A7%86%E5%8F%82%E6%95%B0%22%7C%20OPT1%5B%22%E6%8C%89%E7%9C%9F%E5%AE%9E%E5%8F%82%E6%95%B0%E4%BC%98%E5%8C%96%E5%87%BA%E8%AE%A1%E5%88%92%20A%22%5D%0A%20%20OPT1%20--%3E%20RISK%5B%22%E5%85%B6%E4%BB%96%E5%8F%82%E6%95%B0%E6%B2%BF%E7%94%A8%E8%AE%A1%E5%88%92%20A%3Cbr%2F%3E%E5%80%BE%E6%96%9C%E6%97%B6%E5%8F%AF%E8%83%BD%E6%95%B4%E4%BD%93%E8%B5%B0%E9%94%99%22%5D%0A%20%20PEEK%20--%3E%7C%22%E9%80%9A%E7%94%A8%E8%AE%A1%E5%88%92%22%7C%20OPT2%5B%22%E4%B8%8D%E7%9C%8B%E5%8F%82%E6%95%B0%20%E6%8C%89%E5%B9%B3%E5%9D%87%E9%80%89%E6%8B%A9%E7%8E%87%22%5D%0A%20%20OPT2%20--%3E%20RISK2%5B%22%E6%9E%81%E7%AB%AF%E5%8F%82%E6%95%B0%E4%B9%9F%E8%B5%B0%E5%90%8C%E4%B8%80%E6%9D%A1%E4%B8%AD%E5%BA%B8%E8%B7%AF%E5%BE%84%22%5D%0A%20%20RISK%20--%3E%20FIX%5B%22%E7%BB%9F%E8%AE%A1%E6%88%96%E6%A8%A1%E5%BC%8F%E5%8F%98%E6%9B%B4%E6%97%B6%E5%A4%B1%E6%95%88%E9%87%8D%E4%BC%98%E5%8C%96%22%5D%0A%20%20RISK2%20--%3E%20FIX%0A"})]),fallback:r(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">数字实例：WHERE status=$1 里 99% 的行是 &#39;done&#39;。第一次绑 &#39;failed&#39;（几十行）优化出索引计划；之后参数换成 &#39;done&#39;（几百万行）仍沿用该计划，沿索引逐行回表可能比全表扫描还慢好几倍。</span></p><p>内存：每个缓存计划占解析树与算子树。无界缓存会胀。LRU 淘汰与池的后端寿命耦合。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Selinger 动态规划如何搜连接顺序——那是下一单元第一课。也不讲学习型优化器。依赖理论单元从 Armstrong 公理重开模式侧，与本课执行侧分开。</p><p>后课默认：OLTP 用参数化语句；计划可缓存；统计与模式变必须能失效。查询语言进阶结束：聚合到计划缓存是「把 SQL 用完整」。</p><p>通用计划与窥视计划的选择，要按数据倾斜显式想，不能只开缓存开关。</p><p><span class="marginnote">常见误区：初学者以为预编译只是「跑得快」。它同时把参数挡在解析器之外——值再恶意也只是数据、不会被当成 SQL 语法执行，这正是参数化查询能防 SQL 注入的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预编译分离解析/优化与执行；参数化同时防注入。</li><li>缓存计划摊优化，也可能锁死坏估计；统计变更要失效。</li><li>下一单元依赖理论：从 Armstrong 公理把主干范式课背后的推导补全。</li><li>出处：Selinger et al.；Ramakrishnan and Gehrke；SQL prepared statements。</li></ul>',9))])}const f=p(d,[["render",c]]);export{S as __pageData,f as default};
